// commands.ts - Funções para botões da fita (ribbon)
import { SumarioController } from "../taskpane/sumarioController";
let controller = null;
async function getController() {
    if (!controller) {
        controller = new SumarioController();
        await controller.initialize();
    }
    return controller;
}
async function gerarSumarioTopo(event) {
    try {
        const ctrl = await getController();
        await ctrl.gerarSumario("topo");
        event.completed();
    }
    catch (error) {
        console.error("Erro ao gerar sumário no topo:", error);
        event.completed();
    }
}
async function gerarSumarioRodape(event) {
    try {
        const ctrl = await getController();
        await ctrl.gerarSumario("rodape");
        event.completed();
    }
    catch (error) {
        console.error("Erro ao gerar sumário no rodapé:", error);
        event.completed();
    }
}
async function atualizarSumario(event) {
    try {
        const ctrl = await getController();
        await ctrl.atualizarSumario();
        event.completed();
    }
    catch (error) {
        console.error("Erro ao atualizar sumário:", error);
        event.completed();
    }
}
async function removerSumario(event) {
    try {
        const ctrl = await getController();
        await ctrl.removerSumarioTodos();
        event.completed();
    }
    catch (error) {
        console.error("Erro ao remover sumário:", error);
        event.completed();
    }
}
window.gerarSumarioTopo = gerarSumarioTopo;
window.gerarSumarioRodape = gerarSumarioRodape;
window.atualizarSumario = atualizarSumario;
window.removerSumario = removerSumario;
Office.onReady(() => {
    console.log("Sumário Dinâmico - Commands ready");
});
