// =====================================================================
// Sumário Dinâmico - Gerenciador de Configuração
// Persistência via Office.settings (roaming settings)
// =====================================================================
const SETTINGS_KEY = "sumarioDinamicoConfig";
export class ConfigManager {
    constructor() {
        this.settings = Office.context.roamingSettings;
    }
    async load() {
        return new Promise((resolve) => {
            this.settings.refreshAsync((result) => {
                if (result.status === Office.AsyncResultStatus.Failed) {
                    console.warn("Falha ao carregar configurações:", result.error);
                }
                resolve();
            });
        });
    }
    getConfig() {
        try {
            const stored = this.settings.get(SETTINGS_KEY);
            if (stored) {
                return JSON.parse(stored);
            }
        }
        catch (error) {
            console.warn("Erro ao parsear configurações:", error);
        }
        return {};
    }
    save(config) {
        try {
            this.settings.set(SETTINGS_KEY, JSON.stringify(config));
            this.settings.saveAsync((result) => {
                if (result.status === Office.AsyncResultStatus.Failed) {
                    console.warn("Falha ao salvar configurações:", result.error);
                }
            });
        }
        catch (error) {
            console.warn("Erro ao serializar configurações:", error);
        }
    }
    clear() {
        this.settings.remove(SETTINGS_KEY);
        this.settings.saveAsync(() => { });
    }
}
