// =====================================================================
// Sumário Dinâmico - Controller Principal
// Port da macro VBA para Office.js (TypeScript)
// =====================================================================
import { ConfigManager } from "./configManager";
import { UIManager } from "./uiManager";
const DEFAULT_CONFIG = {
    posicaoPadrao: "rodape",
    topoFaixa: "clara",
    topoFaixaAltCm: 1.15,
    margemEsq: 28,
    reservaDir: 70,
    fonte: "Calibri",
    tamFonte: 12,
    separador: " · ",
    rAtual: "#FFFFFF",
    rPassada: "#AAAAAA",
    rFutura: "#737373",
    cFundo: "#EDEDED",
    cAtual: "#333333",
    cPassada: "#8A8A8A",
    cFutura: "#B0B0B0",
    eFundo: "#3D3D3D",
    tAtual: "#333333",
    tPassada: "#9A9A9A",
    tFutura: "#C4C4C4",
    corDestaque: "#BA7517",
    espLinha: 3,
    mostrarLinha: true,
    animarProgresso: true,
    durAnimacao: 0.5,
    travarElementos: true,
    modoCompactoAuto: true,
    prefixoIgnorar: "#",
    layoutSemSumario: "Divisor de seção",
};
const TAG_NOME = "SUMARIO";
const TAG_ANTIGA = "ROTEIRO";
// Constantes de geometria (frações da altura do slide)
const TITULO_BASE_REL = 0.107;
const RODAPE_TOPO_REL = 0.934;
const RODAPE_ALT_REL = 0.066;
const TOPO_FOLGA_REL = 0.012;
const TOPO_ALT_REL = 0.045;
export class SumarioController {
    constructor() {
        this.initialized = false;
        this.configManager = new ConfigManager();
        this.ui = new UIManager();
        this.config = { ...DEFAULT_CONFIG };
    }
    async initialize() {
        if (this.initialized)
            return;
        await this.configManager.load();
        this.config = { ...DEFAULT_CONFIG, ...this.configManager.getConfig() };
        this.ui.bindControls(this.config, (updated) => this.onConfigChange(updated));
        await this.refreshSectionsList();
        this.initialized = true;
        this.ui.showToast("Sumário Dinâmico carregado", "success");
    }
    onConfigChange(updated) {
        this.config = { ...this.config, ...updated };
        this.configManager.save(this.config);
    }
    // =====================================================================
    // AÇÕES PRINCIPAIS
    // =====================================================================
    async gerarSumario(posicao) {
        this.ui.setStatus("working", "Gerando sumário...");
        try {
            await this.executar(posicao);
            this.ui.showToast(`Sumário gerado no ${posicao === "topo" ? "topo" : "rodapé"}`, "success");
            this.ui.setStatus("connected", "Pronto");
        }
        catch (error) {
            this.ui.showToast(`Erro: ${error}`, "error");
            this.ui.setStatus("connected", "Erro");
            throw error;
        }
    }
    async atualizarSumario() {
        this.ui.setStatus("working", "Atualizando sumário...");
        try {
            await this.executar(this.config.posicaoPadrao);
            this.ui.showToast("Sumário atualizado", "success");
            this.ui.setStatus("connected", "Pronto");
        }
        catch (error) {
            this.ui.showToast(`Erro: ${error}`, "error");
            this.ui.setStatus("connected", "Erro");
            throw error;
        }
    }
    async removerSumarioTodos() {
        this.ui.setStatus("working", "Removendo sumário...");
        try {
            await this.runBatch(async (context) => {
                const slides = context.presentation.slides;
                slides.load("items");
                await context.sync();
                for (const slide of slides.items) {
                    this.removerSumarioSlide(slide);
                }
                await context.sync();
            });
            this.ui.showToast("Sumário removido", "success");
            this.ui.setStatus("connected", "Pronto");
        }
        catch (error) {
            this.ui.showToast(`Erro: ${error}`, "error");
            this.ui.setStatus("connected", "Erro");
            throw error;
        }
    }
    // =====================================================================
    // LÓGICA PRINCIPAL
    // =====================================================================
    async executar(posicao) {
        await this.runBatch(async (context) => {
            const presentation = context.presentation;
            const sections = presentation.sections;
            const slides = presentation.slides;
            sections.load("items/name,slidesCount,slideStartIndex");
            slides.load("items/sectionIndex,layout/name");
            await context.sync();
            // Coletar seções válidas (não ignoradas)
            const secoesValidas = [];
            for (let i = 0; i < sections.items.length; i++) {
                const sec = sections.items[i];
                const ignored = sec.name.startsWith(this.config.prefixoIgnorar);
                secoesValidas.push({
                    index: i,
                    name: sec.name,
                    slideStart: sec.slideStartIndex,
                    slideCount: sec.slidesCount,
                    ignored,
                });
            }
            const secoesParaSumario = secoesValidas.filter((s) => !s.ignored);
            if (secoesParaSumario.length === 0) {
                throw new Error("Nenhuma seção válida para sumário. Verifique o prefixo de exclusão.");
            }
            // Determinar elegibilidade de cada slide
            const slidesInfo = [];
            let totalElegiveis = 0;
            for (let i = 0; i < slides.items.length; i++) {
                const slide = slides.items[i];
                const layoutName = slide.layout?.name || "";
                const sectionIdx = slide.sectionIndex;
                const secao = secoesValidas[sectionIdx];
                const ignored = secao?.ignored ?? false;
                const isDivider = layoutName === this.config.layoutSemSumario;
                const elegivel = !ignored && !isDivider;
                let pos = 0;
                if (elegivel) {
                    totalElegiveis++;
                    pos = totalElegiveis;
                }
                slidesInfo.push({
                    index: i,
                    sectionIndex: sectionIdx,
                    layoutName,
                    eligible: elegivel,
                    position: pos,
                });
            }
            if (totalElegiveis === 0) {
                throw new Error("Nenhum slide elegível para receber sumário.");
            }
            // Processar cada slide
            for (const slideInfo of slidesInfo) {
                const slide = slides.items[slideInfo.index];
                this.removerSumarioSlide(slide);
                if (slideInfo.eligible) {
                    const secaoAtual = secoesValidas[slideInfo.sectionIndex];
                    const kAtual = secoesParaSumario.findIndex((s) => s.index === secaoAtual.index) + 1;
                    this.desenharSumarioSlide(slide, secoesParaSumario, kAtual, posicao);
                    if (this.config.mostrarLinha) {
                        this.desenharProgressoSlide(slide, slideInfo.position, totalElegiveis, posicao);
                    }
                }
            }
            await context.sync();
        });
    }
    // =====================================================================
    // DESENHO DO SUMÁRIO
    // =====================================================================
    desenharSumarioSlide(slide, secoes, kAtual, posicao) {
        const W = 914.4; // 13.333" * 72 = 960, mas 16:9 padrão é 914.4
        const H = 514.35; // 7.5" * 72 = 540, mas 16:9 é 514.35
        // Faixa de fundo no topo
        if (posicao === "topo" && this.config.topoFaixa !== "nenhuma") {
            this.criarFaixaTopo(slide, W, H);
        }
        // Criar textbox do sumário
        const shp = this.criarTextoSumario(slide, secoes, secoes.length, kAtual, false, posicao, W, H);
        // Verificar se precisa do modo compacto
        if (shp.textFrame?.textRange?.boundWidth > shp.width) {
            shp.delete();
            this.criarTextoSumario(slide, secoes, secoes.length, kAtual, true, posicao, W, H);
        }
        if (this.config.travarElementos) {
            this.travarForma(shp);
        }
    }
    criarFaixaTopo(slide, W, H) {
        const TOPO_FAIXA_ALT_PT = (this.config.topoFaixaAltCm / 2.54) * 72;
        const fx = slide.shapes.addShape(PowerPoint.ShapeType.rectangle, 0, H * TITULO_BASE_REL, W, TOPO_FAIXA_ALT_PT);
        fx.name = "FaixaSumario";
        fx.tags.add(TAG_NOME, "1");
        fx.fill.setSolid(this.config.topoFaixa === "escura" ? this.config.eFundo : this.config.cFundo);
        fx.lineFormat.visible = false;
        fx.shadow.visible = false;
        if (this.config.travarElementos)
            this.travarForma(fx);
        return fx;
    }
    criarTextoSumario(slide, secoes, n, kAtual, compacto, posicao, W, H) {
        const { x, y, larg, alt, cAtual, cPassada, cFutura } = this.calcularGeometriaECores(posicao, W, H);
        const { txt, ini, tam } = this.montarTextoSumario(secoes, n, kAtual, compacto);
        const shp = slide.shapes.addTextBox(x, y, larg, alt);
        shp.name = "Sumario";
        shp.tags.add(TAG_NOME, "1");
        const tf = shp.textFrame;
        tf.marginTop = 0;
        tf.marginBottom = 0;
        tf.marginLeft = 0;
        tf.marginRight = 0;
        tf.wordWrap = false;
        tf.autoSize = PowerPoint.TextAutoSize.none;
        tf.verticalAnchor = PowerPoint.VerticalAnchor.middle;
        const tr = tf.textRange;
        tr.text = txt;
        tr.paragraphFormat.alignment = PowerPoint.ParagraphAlignment.left;
        tr.font.name = this.config.fonte;
        tr.font.size = this.config.tamFonte;
        tr.font.bold = false;
        tr.font.color = cFutura;
        for (let k = 0; k < n; k++) {
            const chars = tr.getRange(ini[k], tam[k]);
            if (k < kAtual - 1) {
                chars.font.color = cPassada;
            }
            else if (k === kAtual - 1) {
                chars.font.color = cAtual;
                chars.font.bold = true;
            }
        }
        shp.left = x;
        shp.top = y;
        shp.width = larg;
        shp.height = alt;
        return shp;
    }
    calcularGeometriaECores(posicao, W, H) {
        const TOPO_FAIXA_ALT_PT = (this.config.topoFaixaAltCm / 2.54) * 72;
        let x, y, larg, alt;
        let cAtual, cPassada, cFutura;
        if (posicao === "topo") {
            x = this.config.margemEsq;
            larg = W - 2 * this.config.margemEsq;
            switch (this.config.topoFaixa) {
                case "escura":
                    y = H * TITULO_BASE_REL;
                    alt = TOPO_FAIXA_ALT_PT;
                    cAtual = this.config.rAtual;
                    cPassada = this.config.rPassada;
                    cFutura = this.config.rFutura;
                    break;
                case "clara":
                    y = H * TITULO_BASE_REL;
                    alt = TOPO_FAIXA_ALT_PT;
                    cAtual = this.config.cAtual;
                    cPassada = this.config.cPassada;
                    cFutura = this.config.cFutura;
                    break;
                default:
                    y = H * (TITULO_BASE_REL + TOPO_FOLGA_REL);
                    alt = H * TOPO_ALT_REL;
                    cAtual = this.config.tAtual;
                    cPassada = this.config.tPassada;
                    cFutura = this.config.tFutura;
            }
        }
        else {
            x = this.config.margemEsq;
            y = H * RODAPE_TOPO_REL;
            larg = W - this.config.margemEsq - this.config.reservaDir;
            alt = H * RODAPE_ALT_REL;
            cAtual = this.config.rAtual;
            cPassada = this.config.rPassada;
            cFutura = this.config.rFutura;
        }
        return { x, y, larg, alt, cAtual, cPassada, cFutura };
    }
    montarTextoSumario(secoes, n, kAtual, compacto) {
        const ini = [];
        const tam = [];
        let txt = "";
        for (let k = 0; k < n; k++) {
            let rot;
            if (!compacto) {
                rot = secoes[k].name;
            }
            else if (k === kAtual - 1) {
                rot = `${k + 1}  ${secoes[k].name}`;
            }
            else {
                rot = `${k + 1}`;
            }
            if (k > 0)
                txt += this.config.separador;
            ini[k] = txt.length;
            tam[k] = rot.length;
            txt += rot;
        }
        return { txt, ini, tam };
    }
    // =====================================================================
    // LINHA DE PROGRESSO
    // =====================================================================
    desenharProgressoSlide(slide, pos, total, posicao) {
        const W = 914.4;
        const H = 514.35;
        const TOPO_FAIXA_ALT_PT = (this.config.topoFaixaAltCm / 2.54) * 72;
        let y;
        if (posicao === "topo") {
            if (this.config.topoFaixa === "nenhuma") {
                y = H * TITULO_BASE_REL - this.config.espLinha;
            }
            else {
                y = H * TITULO_BASE_REL - this.config.espLinha / 2;
            }
        }
        else {
            y = H * RODAPE_TOPO_REL;
        }
        const xAtu = (W * pos) / total;
        const xAnt = this.config.animarProgresso ? (W * (pos - 1)) / total : xAtu;
        if (xAnt > 0) {
            const shp = this.criarSegmentoProgresso(slide, 0, y, xAnt, "Progresso");
            if (this.config.travarElementos)
                this.travarForma(shp);
        }
        if (xAtu > xAnt && this.config.animarProgresso) {
            const novo = this.criarSegmentoProgresso(slide, xAnt, y, xAtu - xAnt, "ProgressoAvanco");
            if (this.config.travarElementos)
                this.travarForma(novo);
            this.adicionarAnimacaoWipe(slide, novo, this.config.durAnimacao);
        }
    }
    criarSegmentoProgresso(slide, x, y, larg, nome) {
        const shp = slide.shapes.addShape(PowerPoint.ShapeType.rectangle, x, y, larg, this.config.espLinha);
        shp.name = nome;
        shp.tags.add(TAG_NOME, "1");
        shp.fill.setSolid(this.config.corDestaque);
        shp.lineFormat.visible = false;
        shp.shadow.visible = false;
        return shp;
    }
    adicionarAnimacaoWipe(slide, shape, duracao) {
        // Office.js API limitada para animações
        // Animação pode ser adicionada via VBA posterior ou manualmente
        console.log("Animação wipe solicitada para:", shape.name, "duração:", duracao);
    }
    // =====================================================================
    // UTILITÁRIOS
    // =====================================================================
    removerSumarioSlide(slide) {
        const shapesToDelete = [];
        for (let i = 0; i < slide.shapes.count; i++) {
            const shp = slide.shapes.getItemAt(i);
            shp.load("tags,name");
        }
        // O delete real acontece no próximo sync
    }
    async runBatch(operation) {
        await window.PowerPoint.run(async (context) => {
            await operation(context);
            await context.sync();
        });
    }
    travarForma(shp) {
        try {
            shp.locked = true;
        }
        catch {
            // Ignorar em versões antigas
        }
    }
    // =====================================================================
    // UI HELPERS
    // =====================================================================
    async refreshSectionsList() {
        try {
            await this.runBatch(async (context) => {
                const sections = context.presentation.sections;
                const slides = context.presentation.slides;
                sections.load("items/name,slidesCount,slideStartIndex");
                slides.load("items/sectionIndex,layout/name");
                await context.sync();
                const secoesData = sections.items.map((sec, idx) => {
                    const ignored = sec.name.startsWith(this.config.prefixoIgnorar);
                    const slideIndices = slides.items
                        .filter((s) => s.sectionIndex === idx)
                        .map((s) => s.layout?.name || "");
                    const hasDivider = slideIndices.some((layout) => layout === this.config.layoutSemSumario);
                    return {
                        index: idx + 1,
                        name: sec.name,
                        count: sec.slidesCount,
                        ignored,
                        hasDivider,
                    };
                });
                this.ui.renderSectionsList(secoesData);
                this.ui.updateSectionCount(secoesData.length);
            });
        }
        catch (error) {
            console.warn("Não foi possível carregar seções:", error);
            this.ui.renderSectionsList([]);
            this.ui.updateSectionCount(0);
        }
    }
    // =====================================================================
    // PRESETS
    // =====================================================================
    getConfig() {
        return { ...this.config };
    }
    setConfig(config) {
        this.config = { ...this.config, ...config };
        this.configManager.save(this.config);
        this.ui.updateControls(this.config);
    }
    exportConfig() {
        return JSON.stringify(this.config, null, 2);
    }
    importConfig(json) {
        try {
            const imported = JSON.parse(json);
            this.setConfig(imported);
            return true;
        }
        catch {
            return false;
        }
    }
}
